{
  "name": "uncle",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Uncle: meet yourself at 70, in AR, in your own aged voice.",
  "scripts": {
    "start": "node --env-file-if-exists=.env server/index.js",
    "test": "node --test server/"
  },
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "express": "^4.21.2"
  }
}

// Which features are on, based on which keys are in the environment.
// The server must start with no keys at all and say what is off (AGENTS.md).

const FEATURES = [
  {
    name: "voice",
    env: "ELEVENLABS_API_KEY",
    off: "ElevenLabs voice clone and speech are off; the sample voice or text is used instead",
  },
  {
    name: "gemini",
    env: "GEMINI_API_KEY",
    off: "Interview field extraction and the Gemini fallback voice are off",
  },
  {
    name: "model",
    env: "MODEL_URL",
    off: "The fine-tuned model is off; Gemini (if on) writes the future self's words",
  },
  {
    name: "aging",
    env: "AGING_URL",
    off: "The face-aging service is off; saved aged heads are used",
  },
];

export function featureStatus(env = process.env) {
  return FEATURES.map(({ name, env: key, off }) => {
    const on = Boolean(env[key] && env[key].trim());
    return { name, on, needs: key, ...(on ? {} : { note: off }) };
  });
}

import express from "express";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { featureStatus } from "./features.js";

const here = path.dirname(fileURLToPath(import.meta.url));

export function createApp() {
  const app = express();

  app.get("/health", (_req, res) => {
    res.json({ ok: true, features: featureStatus() });
  });

  app.use(express.static(path.join(here, "public")));
  return app;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  createApp().listen(port, () => {
    console.log(`Uncle server listening on port ${port}`);
    for (const f of featureStatus()) {
      console.log(`  ${f.on ? "on " : "OFF"} ${f.name}${f.on ? "" : `: ${f.note} (set ${f.needs})`}`);
    }
  });
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { featureStatus } from "./features.js";
import { createApp } from "./index.js";

test("with no keys every feature is off and says why", () => {
  const status = featureStatus({});
  assert.ok(status.length > 0);
  for (const f of status) {
    assert.equal(f.on, false);
    assert.ok(f.note, `${f.name} should explain what is off`);
  }
});

test("a key turns its feature on; a blank key does not", () => {
  const status = featureStatus({ ELEVENLABS_API_KEY: "abc", GEMINI_API_KEY: "  " });
  assert.equal(status.find((f) => f.name === "voice").on, true);
  assert.equal(status.find((f) => f.name === "gemini").on, false);
});

test("/health answers without any keys", async () => {
  const server = createApp().listen(0);
  try {
    const { port } = server.address();
    const res = await fetch(`http://127.0.0.1:${port}/health`);
    assert.equal(res.status, 200);
    const body = await res.json();
    assert.equal(body.ok, true);
    assert.ok(Array.isArray(body.features));
  } finally {
    server.close();
  }
});

