// Uncle's voice aging filter: our own audio code (PLAN.md Part 4).
// Works on mono Float32 samples in [-1, 1]. No dependencies.
//
// Five changes, each with its own amount: pitch, pace, wobble (vibrato + tremor),
// breathiness, tone. See aging.js for how the amounts are chosen.

// Small seeded random numbers so the same input always gives the same output.
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Play the samples back faster (ratio > 1: higher pitch, shorter) or slower.
export function resample(x, ratio) {
  if (x.length < 2 || Math.abs(ratio - 1) < 1e-6) return x;
  const n = Math.floor((x.length - 1) / ratio);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const p = i * ratio;
    const i0 = Math.floor(p);
    const f = p - i0;
    out[i] = x[i0] * (1 - f) + x[i0 + 1] * f;
  }
  return out;
}

// Make the audio s times longer without changing its pitch (WSOLA).
export function timeStretch(x, s, sr = 24000) {
  if (Math.abs(s - 1) < 1e-4 || x.length < 4096) return x;
  const N = 1024; // frame length
  const H = N / 2; // output hop (50% overlap, Hann window sums to 1)
  const anaHop = H / s;
  const tol = Math.round(0.006 * sr); // search +/- 6 ms for the best join
  const win = new Float32Array(N);
  for (let i = 0; i < N; i++) win[i] = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / N);

  const outLen = Math.round(x.length * s);
  const out = new Float32Array(outLen + N);
  const maxStart = x.length - N;
  let prev = 0;
  for (let k = 0; ; k++) {
    const outPos = k * H;
    if (outPos >= outLen) break;
    const nominal = Math.round(k * anaHop);
    let p;
    if (k === 0) {
      p = 0;
    } else {
      // The frame that would naturally follow the previous one.
      const ref = Math.min(prev + H, maxStart);
      const lo = Math.max(0, nominal - tol);
      const hi = Math.min(maxStart, nominal + tol);
      if (lo > hi) break;
      let best = -Infinity;
      p = lo;
      for (let c = lo; c <= hi; c++) {
        let dot = 0;
        let e = 1e-9;
        for (let i = 0; i < N; i += 2) {
          const v = x[c + i];
          dot += v * x[ref + i];
          e += v * v;
        }
        const score = dot / Math.sqrt(e);
        if (score > best) {
          best = score;
          p = c;
        }
      }
    }
    for (let i = 0; i < N; i++) out[outPos + i] += x[p + i] * win[i];
    prev = p;
  }
  return out.subarray(0, outLen);
}

// Pitch shift in semitones, then slow down (speed < 1) or speed up, keeping both independent.
export function pitchAndPace(x, sr, { pitchSemitones = 0, speed = 1 } = {}) {
  const ratio = Math.pow(2, pitchSemitones / 12);
  const shifted = resample(x, ratio); // pitch * ratio, duration / ratio
  // Want final duration = original / speed, so stretch by ratio / speed.
  return timeStretch(shifted, ratio / speed, sr);
}

// Wobble: slow pitch drift (vibrato) and loudness drift (tremor).
// vibrato = rough peak pitch deviation as a fraction (0.01 = 1%). tremor = loudness swing fraction.
export function wobble(x, sr, { vibrato = 0, tremor = 0, seed = 7 } = {}) {
  if (!vibrato && !tremor) return x;
  const rand = rng(seed);
  const f1 = 4.8;
  const f2 = 6.9;
  const ph1 = rand() * 2 * Math.PI;
  const ph2 = rand() * 2 * Math.PI;
  const ph3 = rand() * 2 * Math.PI;
  const D = (vibrato * sr) / (2 * Math.PI * 5.5); // delay swing in samples
  const base = Math.ceil(D) + 2;
  const out = new Float32Array(x.length);
  for (let n = 0; n < x.length; n++) {
    const t = n / sr;
    const m = 0.6 * Math.sin(2 * Math.PI * f1 * t + ph1) + 0.4 * Math.sin(2 * Math.PI * f2 * t + ph2);
    const pos = n - (base + D * m);
    let v = 0;
    if (pos >= 0) {
      const i0 = Math.floor(pos);
      const f = pos - i0;
      v = x[i0] * (1 - f) + (x[i0 + 1] ?? 0) * f;
    }
    const g = 1 + tremor * Math.sin(2 * Math.PI * 5.2 * t + ph3);
    out[n] = v * g;
  }
  return out;
}

// Tone: turn the brightness down a little. cut 0 = unchanged, 1 = everything above ~3 kHz gone.
export function tone(x, sr, { cut = 0, cutoffHz = 3000 } = {}) {
  if (!cut) return x;
  const alpha = 1 - Math.exp((-2 * Math.PI * cutoffHz) / sr);
  const out = new Float32Array(x.length);
  let lp = 0;
  for (let n = 0; n < x.length; n++) {
    lp += alpha * (x[n] - lp);
    out[n] = x[n] - cut * (x[n] - lp);
  }
  return out;
}

// Breathiness: shaped noise that follows the voice's loudness, so it never hisses in silence.
export function breath(x, sr, { mix = 0, seed = 11 } = {}) {
  if (!mix) return x;
  const rand = rng(seed);
  const aHp = 1 - Math.exp((-2 * Math.PI * 1500) / sr);
  const aEnv = 1 - Math.exp(-1 / (0.02 * sr));
  const out = new Float32Array(x.length);
  let lp = 0;
  let env = 0;
  for (let n = 0; n < x.length; n++) {
    const noise = rand() * 2 - 1;
    lp += aHp * (noise - lp);
    const hp = noise - lp; // noise with the lows removed
    env += aEnv * (Math.abs(x[n]) - env);
    out[n] = x[n] + mix * hp * env * 2;
  }
  return out;
}

function limit(x) {
  let peak = 0;
  for (let i = 0; i < x.length; i++) peak = Math.max(peak, Math.abs(x[i]));
  if (peak <= 0.98) return x;
  const g = 0.98 / peak;
  const out = new Float32Array(x.length);
  for (let i = 0; i < x.length; i++) out[i] = x[i] * g;
  return out;
}

// params: { pitchSemitones, speed, vibrato, tremor, breath, toneCut }
export function applyAging(x, sr, params = {}) {
  let y = pitchAndPace(x, sr, { pitchSemitones: params.pitchSemitones, speed: params.speed });
  y = wobble(y, sr, { vibrato: params.vibrato, tremor: params.tremor });
  y = tone(y, sr, { cut: params.toneCut });
  y = breath(y, sr, { mix: params.breath });
  return limit(y);
}

// How much of each aging change to apply, from "how aged" (0 = none, 1 = full age 70).
//
// PROVISIONAL: these sizes are first guesses chosen to sound subtle, NOT yet checked
// against voice-aging research. PLAN.md Part 4 says to check each size against research and
// cite it before tuning. TODO(Jeffrey's Claude): research and cite each number below.
// Direction (per PLAN.md): women's pitch tends to drop with age, men's can rise slightly.

export const FULL_AGING = {
  female: { pitchSemitones: -1.5, speed: 0.92, vibrato: 0.012, tremor: 0.06, breath: 0.2, toneCut: 0.35 },
  male: { pitchSemitones: 0.7, speed: 0.92, vibrato: 0.012, tremor: 0.06, breath: 0.2, toneCut: 0.35 },
  // Used when sex is unknown: no pitch change, everything else the same.
  neutral: { pitchSemitones: 0, speed: 0.92, vibrato: 0.012, tremor: 0.06, breath: 0.2, toneCut: 0.35 },
};

export function agingParams(strength = 1, sex = "neutral") {
  const s = Math.min(1, Math.max(0, strength));
  const full = FULL_AGING[sex] ?? FULL_AGING.neutral;
  return {
    pitchSemitones: full.pitchSemitones * s,
    speed: 1 + (full.speed - 1) * s,
    vibrato: full.vibrato * s,
    tremor: full.tremor * s,
    breath: full.breath * s,
    toneCut: full.toneCut * s,
  };
}

// Raw 16-bit little-endian mono PCM <-> Float32 samples, and a WAV file wrapper.

export function pcm16ToFloat(buf) {
  const n = Math.floor(buf.length / 2);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) out[i] = buf.readInt16LE(i * 2) / 32768;
  return out;
}

export function floatToWav(samples, sampleRate) {
  const dataBytes = samples.length * 2;
  const buf = Buffer.alloc(44 + dataBytes);
  buf.write("RIFF", 0);
  buf.writeUInt32LE(36 + dataBytes, 4);
  buf.write("WAVE", 8);
  buf.write("fmt ", 12);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20); // PCM
  buf.writeUInt16LE(1, 22); // mono
  buf.writeUInt32LE(sampleRate, 24);
  buf.writeUInt32LE(sampleRate * 2, 28);
  buf.writeUInt16LE(2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write("data", 36);
  buf.writeUInt32LE(dataBytes, 40);
  for (let i = 0; i < samples.length; i++) {
    const v = Math.max(-1, Math.min(1, samples[i]));
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  return buf;
}

// ElevenLabs text-to-speech. Returns raw samples so our aging filter can work on them.
import { pcm16ToFloat } from "./wav.js";

export const SAMPLE_RATE = 24000;
// "Will": a premade stock voice, standing in for the user's own clone until we have one.
export const DEFAULT_VOICE_ID = "bIHbv24MWmeRgasZH58o";
const MODEL_ID = "eleven_flash_v2_5"; // lowest-latency model

export async function speak(text, { apiKey = process.env.ELEVENLABS_API_KEY, voiceId } = {}) {
  if (!apiKey) throw new Error("voice is off: set ELEVENLABS_API_KEY");
  const voice = voiceId || process.env.ELEVENLABS_VOICE_ID || DEFAULT_VOICE_ID;
  const url = `https://api.elevenlabs.io/v1/text-to-speech/${voice}?output_format=pcm_${SAMPLE_RATE}`;
  const t0 = performance.now();
  const res = await fetch(url, {
    method: "POST",
    headers: { "xi-api-key": apiKey, "content-type": "application/json" },
    body: JSON.stringify({ text, model_id: MODEL_ID }),
  });
  const ttfbMs = performance.now() - t0; // time until the response started
  if (!res.ok) {
    const detail = (await res.text()).slice(0, 200);
    throw new Error(`ElevenLabs ${res.status}: ${detail}`);
  }
  const bytes = Buffer.from(await res.arrayBuffer());
  return {
    samples: pcm16ToFloat(bytes),
    sampleRate: SAMPLE_RATE,
    ttfbMs: Math.round(ttfbMs),
    totalMs: Math.round(performance.now() - t0),
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { applyAging, pitchAndPace, tone, breath, wobble } from "./filter.js";
import { agingParams } from "./aging.js";
import { floatToWav, pcm16ToFloat } from "./wav.js";

const SR = 24000;

// A voice-like test signal: a 150 Hz fundamental with a few harmonics.
function voiceLike(seconds, f0 = 150) {
  const x = new Float32Array(Math.round(seconds * SR));
  for (let n = 0; n < x.length; n++) {
    const t = n / SR;
    let v = 0;
    for (let h = 1; h <= 5; h++) v += Math.sin(2 * Math.PI * f0 * h * t) / h;
    x[n] = 0.3 * v;
  }
  return x;
}

// Estimate the fundamental frequency from the middle of the signal (autocorrelation).
function estimateF0(x) {
  const mid = Math.floor(x.length / 2);
  const len = 6000;
  const seg = x.subarray(mid, mid + len + SR / 60);
  const scores = [];
  for (let lag = Math.floor(SR / 400); lag <= Math.floor(SR / 60); lag++) {
    let dot = 0;
    let e1 = 1e-9;
    let e2 = 1e-9;
    for (let i = 0; i < len; i++) {
      dot += seg[i] * seg[i + lag];
      e1 += seg[i] * seg[i];
      e2 += seg[i + lag] * seg[i + lag];
    }
    scores.push({ lag, s: dot / Math.sqrt(e1 * e2) });
  }
  const max = Math.max(...scores.map((o) => o.s));
  const first = scores.find((o) => o.s >= 0.95 * max);
  return SR / first.lag;
}

const rms = (x) => Math.sqrt(x.reduce((a, v) => a + v * v, 0) / x.length);

test("test signal's pitch is measured correctly", () => {
  const f0 = estimateF0(voiceLike(2));
  assert.ok(Math.abs(f0 - 150) < 3, `got ${f0}`);
});

test("pitch up 3 semitones raises pitch ~19% and keeps the length", () => {
  const x = voiceLike(3);
  const y = pitchAndPace(x, SR, { pitchSemitones: 3, speed: 1 });
  const ratio = estimateF0(y) / estimateF0(x);
  assert.ok(Math.abs(ratio - 1.1892) < 0.03, `pitch ratio ${ratio}`);
  assert.ok(Math.abs(y.length / x.length - 1) < 0.02, `length ratio ${y.length / x.length}`);
});

test("slower pace stretches the length and leaves the pitch alone", () => {
  const x = voiceLike(3);
  const y = pitchAndPace(x, SR, { pitchSemitones: 0, speed: 0.9 });
  assert.ok(Math.abs(y.length / x.length - 1 / 0.9) < 0.02, `length ratio ${y.length / x.length}`);
  const ratio = estimateF0(y) / estimateF0(x);
  assert.ok(Math.abs(ratio - 1) < 0.03, `pitch ratio ${ratio}`);
});

test("tone cut lowers the high-frequency energy", () => {
  const x = new Float32Array(SR);
  for (let n = 0; n < x.length; n++) x[n] = 0.3 * Math.sin((2 * Math.PI * 8000 * n) / SR);
  const y = tone(x, SR, { cut: 0.5 });
  assert.ok(rms(y) < 0.7 * rms(x));
});

test("no aging changes nothing", () => {
  const x = voiceLike(1);
  const y = applyAging(x, SR, agingParams(0));
  assert.equal(y.length, x.length);
  for (let i = 0; i < x.length; i += 997) assert.ok(Math.abs(y[i] - x[i]) < 1e-6);
});

test("breathiness and wobble keep silence silent", () => {
  const silence = new Float32Array(SR);
  assert.equal(rms(breath(silence, SR, { mix: 0.5 })), 0);
  assert.equal(rms(wobble(silence, SR, { vibrato: 0.02, tremor: 0.1 })), 0);
});

test("full aging stays inside the audio range and has a similar length scale", () => {
  const x = voiceLike(2);
  for (const sex of ["female", "male", "neutral"]) {
    const y = applyAging(x, SR, agingParams(1, sex));
    let peak = 0;
    for (const v of y) peak = Math.max(peak, Math.abs(v));
    assert.ok(peak <= 0.981, `${sex} peak ${peak}`);
    assert.ok(y.length > x.length, `${sex} should be slower, so longer`);
  }
});

test("wav round trip keeps the samples", () => {
  const x = voiceLike(0.1);
  const wav = floatToWav(x, SR);
  assert.equal(wav.toString("ascii", 0, 4), "RIFF");
  const back = pcm16ToFloat(wav.subarray(44));
  assert.equal(back.length, x.length);
  assert.ok(Math.abs(back[100] - x[100]) < 1e-3);
});

