test("tone cut lowers high frequencies and leaves low ones alone", () => {
  const sine = (hz) => {
    const x = new Float32Array(SR);
    for (let n = 0; n < x.length; n++) x[n] = 0.3 * Math.sin((2 * Math.PI * hz * n) / SR);
    return x;
  };
  const high = sine(8000);
  const low = sine(200);
