// Breathiness: a soft, steady bed of air under the voice.
// The noise level follows a SLOW average of the voice's loudness (tens of ms), not every
// peak. An earlier version followed the loudness closely, and every hard consonant got a
// short burst of hiss that sounded like a snare drum. Noise is also band-limited (2-6 kHz).
export function breath(x, sr, { mix = 0, seed = 11 } = {}) {
  if (!mix) return x;
  const rand = rng(seed);
  const aHp = 1 - Math.exp((-2 * Math.PI * 2000) / sr); // remove everything below ~2 kHz
  const aLp = 1 - Math.exp((-2 * Math.PI * 6000) / sr); // remove everything above ~6 kHz
  const aUp = 1 - Math.exp(-1 / (0.03 * sr)); // level rises over ~30 ms
  const aDown = 1 - Math.exp(-1 / (0.06 * sr)); // and falls over ~60 ms
  const out = new Float32Array(x.length);
  let lowTrack = 0;
  let band = 0;
  let power = 0;
  for (let n = 0; n < x.length; n++) {
    const noise = rand() * 2 - 1;
    lowTrack += aHp * (noise - lowTrack);
    const highPassed = noise - lowTrack;
    band += aLp * (highPassed - band);
    const sq = x[n] * x[n];
    power += (sq > power ? aUp : aDown) * (sq - power);
    out[n] = x[n] + mix * band * Math.sqrt(power);
  }
  return out;
}

test("breath is a quiet, steady bed: well under the voice, and no bursts on sudden sounds", () => {
  // Voice-like signal with hard on/off bursts, like consonants.
  const x = voiceLike(2);
  for (let n = 0; n < x.length; n++) if (Math.floor(n / 1200) % 4 === 0) x[n] = 0;
  const y = breath(x, SR, { mix: agingParams(1).breath });
  const added = new Float32Array(x.length);
  for (let i = 0; i < x.length; i++) added[i] = y[i] - x[i];
  assert.ok(rms(added) < 0.1 * rms(x), `noise ${rms(added) / rms(x)} of the voice level (want < 0.1)`);
  // Right after a sound stops, the noise must fade out gently, not stay at full level or spike.
  const spikeWindow = (start) => rms(added.subarray(start, start + 120));
  const peakWindow = Math.max(...[...Array(20)].map((_, k) => spikeWindow(2400 + k * 120)));
  assert.ok(peakWindow < 0.1 * rms(x), "no burst louder than 10% of the voice");
});

