// The /voice WebSocket (CONTRACTS.md "Voice pipeline").
//
// Implemented so far (the agreed parts of the contract):
//   client -> {type:"text", question}                  a typed or confirmed question
//   server -> {type:"reply", sentence, audio, done}    one message per sentence; audio is base64 PCM
// Additive extras (clients that ignore unknown fields are unaffected):
//   reply.sampleRate   always 24000, 16-bit little-endian mono PCM
//   reply.ms           milliseconds since the question arrived (for measuring delay)
//   reply.audio = null when the voice is off: the headset shows the text only (text fallback)
//   {type:"error", feature, message}
// NOT built yet: {type:"audio"} mic input (needs speech-to-text), transcript messages,
// and the proposed start/age/status messages (waiting for Ethan to agree them).
import { WebSocketServer } from "ws";
import { speak as realSpeak } from "../voice/tts.js";
import { applyAging } from "../voice/filter.js";
import { agingParams, strengthForAge } from "../voice/aging.js";
import { floatToPcm16 } from "../voice/wav.js";
import { getFacts as realGetFacts } from "../sim/facts.js";
import { answer } from "./brain.js";

const MAX_QUESTION = 500;

function send(ws, obj) {
  if (ws.readyState === ws.OPEN) ws.send(JSON.stringify(obj));
}

async function replyTo(ws, question, { speakFn, getFacts, sex }) {
  const started = performance.now();
  const facts = getFacts();
  const sentences = answer(question, facts);
  const strength = strengthForAge(facts.apparent_age_at_70);

  // Start every sentence's speech at once, then send them in order: sentence 1 plays
  // while 2 and 3 are still being made.
  const jobs = sentences.map((s) => speakFn(s).then((tts) => ({ tts }), (error) => ({ error })));

  let reportedError = false;
  for (let i = 0; i < sentences.length; i++) {
    const { tts, error } = await jobs[i];
    let audio = null;
    let sampleRate = 24000;
    if (tts) {
      const aged = applyAging(tts.samples, tts.sampleRate, agingParams(strength, sex));
      audio = floatToPcm16(aged).toString("base64");
      sampleRate = tts.sampleRate;
    } else if (!reportedError) {
      reportedError = true;
      send(ws, { type: "error", feature: "voice", message: error?.message ?? "voice failed" });
    }
    send(ws, {
      type: "reply",
      sentence: sentences[i],
      audio,
      sampleRate,
      done: i === sentences.length - 1,
      ms: Math.round(performance.now() - started),
    });
  }
}

export function attachVoice(httpServer, { speakFn = realSpeak, getFacts = realGetFacts, sex = "neutral" } = {}) {
  const wss = new WebSocketServer({ server: httpServer, path: "/voice", maxPayload: 4 * 1024 * 1024 });

  wss.on("connection", (ws) => {
    let queue = Promise.resolve(); // answer one question at a time, in order

    ws.on("message", (raw) => {
      let msg;
      try {
        msg = JSON.parse(raw.toString());
      } catch {
        return send(ws, { type: "error", feature: "protocol", message: "messages must be JSON" });
      }
      if (msg?.type === "text") {
        const question = String(msg.question ?? "").trim().slice(0, MAX_QUESTION);
        if (!question) return send(ws, { type: "error", feature: "protocol", message: "question is empty" });
        queue = queue
          .then(() => replyTo(ws, question, { speakFn, getFacts, sex }))
          .catch((err) => send(ws, { type: "error", feature: "voice", message: err.message }));
      } else if (msg?.type === "audio") {
        send(ws, { type: "error", feature: "speech-to-text", message: "microphone input is not built yet" });
      }
      // Unknown types are ignored, so newer clients don't break older servers.
    });
  });

  return wss;
}

