// ---- talk to your future self, over the /voice WebSocket (CONTRACTS.md) ----
let ctx, socket, nextStart = 0, askedAt = 0, gotFirst = false;
function ensureSocket() {
  if (socket && socket.readyState <= 1) return socket;
  socket = new WebSocket((location.protocol === "https:" ? "wss://" : "ws://") + location.host + "/voice");
  socket.onmessage = (e) => onMessage(JSON.parse(e.data));
  return socket;
}
function playPcm(b64, sampleRate) {
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const pcm = new Int16Array(bytes.buffer, 0, bytes.length >> 1);
  const buf = ctx.createBuffer(1, pcm.length, sampleRate);
  const ch = buf.getChannelData(0);
  for (let i = 0; i < pcm.length; i++) ch[i] = pcm[i] / 32768;
  const src = ctx.createBufferSource();
  src.buffer = buf;
  src.connect(ctx.destination);
  nextStart = Math.max(nextStart, ctx.currentTime + 0.02); // sentences play back to back
  src.start(nextStart);
  nextStart += buf.duration;
}
function onMessage(m) {
  if (m.type === "reply") {
    const p = document.createElement("p");
    p.textContent = "Future you: " + m.sentence;
    $("chat").appendChild(p);
    if (m.audio) playPcm(m.audio, m.sampleRate);
    if (!gotFirst) {
      gotFirst = true;
      $("chatStatus").textContent = `First sentence arrived ${Math.round(performance.now() - askedAt)} ms after you asked (server measured ${m.ms} ms).`;
    }
  } else if (m.type === "error") {
    $("chatStatus").textContent = `(${m.feature}: ${m.message})`;
  }
}
$("askForm").onsubmit = (e) => {
  e.preventDefault();
  const q = $("question").value.trim();
  if (!q) return;
  ctx = ctx || new AudioContext(); // created on a click, so the browser allows sound
  ctx.resume();
  const p = document.createElement("p");
  p.textContent = "You: " + q;
  $("chat").appendChild(p);
  $("question").value = "";
  gotFirst = false;
  askedAt = performance.now();
  const ws = ensureSocket();
  const msg = JSON.stringify({ type: "text", question: q });
  if (ws.readyState === 1) ws.send(msg); else ws.addEventListener("open", () => ws.send(msg), { once: true });
};

$("raw").onclick = () => play(true);

