// ElevenLabs Instant Voice Clone: make a copy of someone's voice from a recording,
// and delete it again. The recording is the interview audio (PLAN.md Part 4).

const API = "https://api.elevenlabs.io/v1";

const EXT = { "audio/webm": "webm", "audio/ogg": "ogg", "audio/mp4": "m4a", "audio/mpeg": "mp3", "audio/wav": "wav", "audio/x-wav": "wav" };

export function extensionFor(mime = "") {
  return EXT[mime.split(";")[0].trim().toLowerCase()] ?? "webm";
}

export async function createClone({ name, audio, mime, apiKey = process.env.ELEVENLABS_API_KEY, fetchFn = fetch }) {
  if (!apiKey) throw new Error("voice is off: set ELEVENLABS_API_KEY");
  const form = new FormData();
  form.append("name", `Uncle - ${name}`);
  form.append("description", "Uncle hackathon demo clone. Delete via the app.");
  // Hackathon rooms are noisy; let ElevenLabs clean the recording first.
  form.append("remove_background_noise", "true");
  form.append("files", new Blob([audio], { type: mime || "audio/webm" }), `${name}.${extensionFor(mime)}`);
  const res = await fetchFn(`${API}/voices/add`, { method: "POST", headers: { "xi-api-key": apiKey }, body: form });
  if (!res.ok) throw new Error(`ElevenLabs ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const body = await res.json();
  if (!body.voice_id) throw new Error("ElevenLabs did not return a voice id");
  return { voiceId: body.voice_id };
}

export async function deleteClone({ voiceId, apiKey = process.env.ELEVENLABS_API_KEY, fetchFn = fetch }) {
  if (!apiKey) throw new Error("voice is off: set ELEVENLABS_API_KEY");
  const res = await fetchFn(`${API}/voices/${encodeURIComponent(voiceId)}`, { method: "DELETE", headers: { "xi-api-key": apiKey } });
  // 404 means it is already gone, which is what we wanted.
  if (!res.ok && res.status !== 404) throw new Error(`ElevenLabs ${res.status}: ${(await res.text()).slice(0, 300)}`);
}

// Saved voice clones, so a judge who comes back doesn't redo the interview (PLAN.md Part 4).
// Stored on disk under voice/saved/ (clone list) and recordings/ (the audio). Both are
// git-ignored: people's voices never go in git.
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

// "Jeffrey W." -> "jeffrey-w". Used as the lookup key and in file names.
export function slug(name) {
  return String(name ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
}

export function createStore({ dir = path.join(root, "voice", "saved"), recordingsDir = path.join(root, "recordings") } = {}) {
  const file = path.join(dir, "clones.json");

  function load() {
    try {
      return existsSync(file) ? JSON.parse(readFileSync(file, "utf8")) : {};
    } catch {
      return {}; // a damaged file should not take the app down
    }
  }
  function write(all) {
    mkdirSync(dir, { recursive: true });
    writeFileSync(file, JSON.stringify(all, null, 2));
  }

  return {
    find: (name) => load()[slug(name)] ?? null,
    list: () => Object.values(load()),
    save({ name, voiceId }) {
      const key = slug(name);
      if (!key) throw new Error("a name is needed");
      const all = load();
      all[key] = { name: String(name).trim().slice(0, 60), key, voiceId, createdAt: new Date().toISOString() };
      write(all);
      return all[key];
    },
    remove(name) {
      const all = load();
      const found = all[slug(name)] ?? null;
      delete all[slug(name)];
      write(all);
      return found;
    },
    saveRecording({ name, audio, ext }) {
      mkdirSync(recordingsDir, { recursive: true });
      const p = path.join(recordingsDir, `${slug(name)}-${Date.now()}.${ext}`);
      writeFileSync(p, audio);
      return p;
    },
  };
}

// HTTP routes for voice clones.
//   POST   /api/voice/clone?name=Jeffrey   body = the recording (any audio type). Makes a clone.
//   GET    /api/voice/clones               who has a saved clone (names only, no voice ids)
//   DELETE /api/voice/clones/:name         delete the clone at ElevenLabs and our saved copy
import express from "express";
import { createClone, deleteClone, extensionFor } from "../voice/clone.js";
import { createStore, slug } from "../voice/store.js";

const MIN_BYTES = 20_000; // anything smaller is under a second or two: too short to clone
const MAX_BYTES = 25 * 1024 * 1024;

export function cloneRoutes({ store = createStore(), createFn = createClone, deleteFn = deleteClone } = {}) {
  const router = express.Router();

  router.post("/clone", express.raw({ type: () => true, limit: MAX_BYTES }), async (req, res) => {
    const name = String(req.query.name ?? "").trim();
    if (!slug(name)) return res.status(400).json({ error: "Please enter a name." });
    const audio = req.body;
    if (!Buffer.isBuffer(audio) || audio.length < MIN_BYTES) {
      return res.status(400).json({ error: "That recording is too short. Please record at least 30 seconds." });
    }
    const mime = req.get("content-type") || "audio/webm";
    try {
      // Replace an older clone for the same name, so we never pile up unused voices.
      const old = store.find(name);
      if (old) await deleteFn({ voiceId: old.voiceId }).catch(() => {});
      store.saveRecording({ name, audio, ext: extensionFor(mime) });
      const { voiceId } = await createFn({ name, audio, mime });
      const saved = store.save({ name, voiceId });
      res.json({ name: saved.name, createdAt: saved.createdAt });
    } catch (err) {
      const off = /voice is off/.test(err.message);
      res.status(off ? 503 : 502).json({ error: err.message });
    }
  });

  router.get("/clones", (_req, res) => {
    res.json(store.list().map(({ name, createdAt }) => ({ name, createdAt })));
  });

  router.delete("/clones/:name", async (req, res) => {
    const found = store.find(req.params.name);
    if (!found) return res.status(404).json({ error: "No saved voice with that name." });
    try {
      await deleteFn({ voiceId: found.voiceId });
      store.remove(req.params.name);
      res.json({ deleted: found.name });
    } catch (err) {
      res.status(502).json({ error: err.message });
    }
  });

  return router;
}

