      model,
      onPartial: (t) => !done && console.log(`  [${model}] partial @${Math.round(performance.now() - t0)}ms: ${t}`),
      onTranscript: (t) => { done = true; console.log(`[${model}] COMMITTED "${t}" -- ${Math.round(performance.now() - lastSpeechSentAt)} ms after the last speech chunk was sent`); s.close(); resolve(); },
      onError: (e) => { console.log(`[${model}] ERROR ${e}`); s.close(); resolve(); },
    });
    (async () => {
      const chunk = 3200; // 100 ms
      for (let i = 0; i < all.length; i += chunk) {
