// Pure audio helpers for the microphone (no browser APIs, so they are testable in Node).
// The headset's mic runs at the device rate (often 48000 Hz); the /voice socket wants
// 16-bit mono PCM at 16000 Hz, base64 (CONTRACTS.md "Voice pipeline").

// Float samples at fromRate -> float samples at toRate (averaging when going down, so it doesn't alias).
export function resampleTo(samples, fromRate, toRate = 16000) {
  if (fromRate === toRate) return samples;
  const ratio = fromRate / toRate;
  const n = Math.floor(samples.length / ratio);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const start = i * ratio;
    const end = Math.min(samples.length, (i + 1) * ratio);
    let sum = 0;
    let count = 0;
    for (let j = Math.floor(start); j < end; j++) (sum += samples[j]), count++;
    out[i] = count ? sum / count : 0;
  }
  return out;
}

// Float samples -> base64 of 16-bit little-endian PCM.
export function toBase64Pcm16(samples) {
  const bytes = new Uint8Array(samples.length * 2);
  const view = new DataView(bytes.buffer);
  for (let i = 0; i < samples.length; i++) {
    const v = Math.max(-1, Math.min(1, samples[i]));
    view.setInt16(i * 2, Math.round(v * 32767), true);
  }
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}

// Collects tiny blocks from the browser's audio thread and hands back ~100 ms chunks.
export function makeChunker(sourceRate, onChunk, chunkMs = 100) {
  const target = Math.round((sourceRate * chunkMs) / 1000);
  let buf = new Float32Array(0);
  return (block) => {
    const merged = new Float32Array(buf.length + block.length);
    merged.set(buf);
    merged.set(block, buf.length);
    buf = merged;
    while (buf.length >= target) {
      onChunk(buf.slice(0, target));
      buf = buf.slice(target);
    }
  };
}

// Microphone for the /voice socket. Any page on this server can use it, including the
// headset page in xr/:
//
//   import { startMic } from "/mic.js";
//   const mic = await startMic((base64, sampleRate) => socket.send(JSON.stringify({ type: "audio", data: base64, sampleRate })));
//   ...
//   mic.stop();
//
// The browser asks the person for microphone permission (needs https or localhost).
import { resampleTo, toBase64Pcm16, makeChunker } from "/mic-pcm.js";

const WORKLET = `
class Grab extends AudioWorkletProcessor {
  process(inputs) {
    const ch = inputs[0] && inputs[0][0];
    if (ch) this.port.postMessage(ch.slice());
    return true;
  }
}
registerProcessor("uncle-mic-grab", Grab);
`;

export async function startMic(onChunk, { chunkMs = 100 } = {}) {
  // Echo cancellation matters in a headset: the mic can hear Uncle's voice from the speakers.
  const stream = await navigator.mediaDevices.getUserMedia({
    audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
  });
  const ctx = new AudioContext();
  await ctx.resume();
  const source = ctx.createMediaStreamSource(stream);
  const feed = makeChunker(ctx.sampleRate, (chunk) => onChunk(toBase64Pcm16(resampleTo(chunk, ctx.sampleRate, 16000)), 16000), chunkMs);

  let node;
  try {
    const url = URL.createObjectURL(new Blob([WORKLET], { type: "text/javascript" }));
    await ctx.audioWorklet.addModule(url);
    node = new AudioWorkletNode(ctx, "uncle-mic-grab");
    node.port.onmessage = (e) => feed(e.data);
  } catch {
    // Older browsers: the deprecated but widely supported fallback.
    node = ctx.createScriptProcessor(2048, 1, 1);
    node.onaudioprocess = (e) => feed(new Float32Array(e.inputBuffer.getChannelData(0)));
  }
  // Pull audio through the graph without playing the mic back out loud.
  const mute = ctx.createGain();
  mute.gain.value = 0;
  source.connect(node);
  node.connect(mute);
  mute.connect(ctx.destination);

  return {
    stop() {
      stream.getTracks().forEach((t) => t.stop());
      source.disconnect();
      node.disconnect();
      ctx.close();
    },
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { resampleTo, toBase64Pcm16, makeChunker } from "./public/mic-pcm.js";

test("48 kHz down to 16 kHz keeps a tone's frequency and length", () => {
  const from = 48000;
  const x = new Float32Array(from).map((_, n) => 0.5 * Math.sin((2 * Math.PI * 440 * n) / from)); // 1 s of 440 Hz
  const y = resampleTo(x, from, 16000);
  assert.equal(y.length, 16000);
  let crossings = 0;
  for (let i = 1; i < y.length; i++) if (y[i - 1] < 0 && y[i] >= 0) crossings++;
  assert.ok(Math.abs(crossings - 440) <= 2, `got ${crossings} cycles for 440 Hz`);
  assert.ok(Math.max(...y) > 0.45 && Math.max(...y) < 0.55, "level kept");
});

test("same rate is passed through untouched", () => {
  const x = new Float32Array([0.1, 0.2]);
  assert.equal(resampleTo(x, 16000, 16000), x);
});

test("base64 PCM matches what the server decodes: 16-bit little-endian", () => {
  const b64 = toBase64Pcm16(new Float32Array([0, 0.5, -0.5, 1, -1, 2, -2]));
  const buf = Buffer.from(b64, "base64");
  assert.equal(buf.length, 14);
  assert.equal(buf.readInt16LE(0), 0);
  assert.equal(buf.readInt16LE(2), 16384);
  assert.equal(buf.readInt16LE(4), -16384);
  assert.equal(buf.readInt16LE(6), 32767);
  assert.equal(buf.readInt16LE(8), -32767);
  assert.equal(buf.readInt16LE(10), 32767, "louder than full scale is clipped, not wrapped");
  assert.equal(buf.readInt16LE(12), -32767);
});

test("a long recording encodes without blowing the call stack", () => {
  assert.doesNotThrow(() => toBase64Pcm16(new Float32Array(16000 * 30)));
});

test("tiny audio blocks are collected into ~100 ms chunks, none lost", () => {
  const got = [];
  const feed = makeChunker(48000, (c) => got.push(c.length), 100); // 4800 samples per chunk
  for (let i = 0; i < 100; i++) feed(new Float32Array(128)); // 12800 samples in 128-sample blocks
  assert.deepEqual(got, [4800, 4800]);
  feed(new Float32Array(4800));
  assert.equal(got.length, 3);
});

